use rk3588_boot_support::{DelayUs,Mmio32,RetryAction,bounded_retry};use crate::stage8::PcieBootConfig;
pub const RETRY_MAGIC:u32=0x7072_7374;pub const SCRATCH_MAGIC:u64=0xFF01_0000;pub const SCRATCH_COUNT:u64=0xFF01_0004;pub const PHY_STATUS:u64=0xFD5B_8904;pub const PHY_AUX:u64=0xFD5B_8A04;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PhyInitOutcome{Locked{status:u32,aux:u32},Retry(RetryAction)}
pub fn prepare_and_poll_phy<I:Mmio32+DelayUs>(io:&mut I,cfg:PcieBootConfig)->PhyInitOutcome{if cfg.phy_mode==4{io.write32(0xFD5F807C,0x000F0000);io.write32(0xFEC4000C,0x10001000);io.write32(0xFEC40004,0x10001000);io.delay_us(100)}for(a,v)in[(0xFD8D81C0,0x001F001F),(0xFD8D8150,0x00A00000),(0xFD5B8000,(cfg.phy_mode as u32)|0x00070000),(0xFD7C0A84,0xFFFC0000),(0xFD7C0A88,0xFFFF0000),(0xFD7C0880,0xFFFF0000),(0xFD7C0884,0xFFFF0000),(0xFD7C0898,0xFFFF0000),(0xFD7C089C,0xFFFF0000),(0xFD7C8800,0xFFFF0000),(0xFD7C8A00,0x04000400)]{io.write32(a,v)}io.delay_us(1000);io.write32(0xFD5B8000,0x01000100);io.write32(0xFD7C8A00,0x04000000);io.delay_us(10);io.write32(0xFD7C0A80,0x20000000);io.delay_us(10);let stored=if io.read32(SCRATCH_MAGIC)==RETRY_MAGIC{io.read32(SCRATCH_COUNT)}else{io.write32(SCRATCH_COUNT,0);0};let mut last=(0,0);for _ in 0..500{let st=io.read32(PHY_STATUS);let aux=io.read32(PHY_AUX);last=(st,aux);if st&0xF==0xF{io.write32(SCRATCH_COUNT,0);io.write32(SCRATCH_MAGIC,0);return PhyInitOutcome::Locked{status:st,aux}}io.delay_us(10)}let action=bounded_retry(false,stored,4);if let RetryAction::WarmReset{next_count}=action{io.write32(SCRATCH_COUNT,next_count);io.write32(SCRATCH_MAGIC,RETRY_MAGIC);io.delay_us(1000)}let _=last;PhyInitOutcome::Retry(action)}
#[cfg(test)]mod tests{use super::*;struct M{magic:u32,count:u32,status:u32,writes:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{SCRATCH_MAGIC=>self.magic,SCRATCH_COUNT=>self.count,PHY_STATUS=>self.status,PHY_AUX=>0,_=>0}}fn write32(&mut self,a:u64,v:u32){self.writes+=1;if a==SCRATCH_MAGIC{self.magic=v}if a==SCRATCH_COUNT{self.count=v}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn locked(){let mut m=M{magic:RETRY_MAGIC,count:2,status:0xF,writes:0};let c=PcieBootConfig{phy_mode:0,generation:0,lanes:0};assert!(matches!(prepare_and_poll_phy(&mut m,c),PhyInitOutcome::Locked{status:0xF,..}));assert_eq!((m.magic,m.count),(0,0));}}
